import { Suspense, ViewTransition } from 'react'
import Link from 'next/link'
import { getProduct, products } from '@/lib/products'
import { notFound } from 'next/navigation'

async function ProductDetails({ slug }: { slug: string }) {
  await new Promise((resolve) => setTimeout(resolve, 100))
  const product = getProduct(slug)
  if (!product) notFound()

  return (
    <div className="product-info">
      <h1>{product.name}</h1>
      <p className="product-price">${product.price}</p>
      <p className="product-description">{product.description}</p>
    </div>
  )
}

function DetailsSkeleton() {
  return (
    <div className="product-info">
      <div className="skeleton-text large" />
      <div className="skeleton-text short" />
      <div className="skeleton-text" />
    </div>
  )
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const product = products.find((p) => p.slug === slug)
  if (!product) notFound()

  return (
    <ViewTransition
      enter={{
        'nav-forward': 'nav-forward',
        'nav-back': 'nav-back',
        default: 'none',
      }}
      exit={{
        'nav-forward': 'nav-forward',
        'nav-back': 'nav-back',
        default: 'none',
      }}
      default="none"
    >
      <div>
        <Link href="/" className="back-link" transitionTypes={['nav-back']}>
          ← Back to products
        </Link>
        <div className="product-detail">
          {/* Outside the Suspense boundary, so the hero renders in the same
              commit as the navigation and pairs with the grid thumbnail. */}
          <ViewTransition
            name={`product-image-${product.slug}`}
            share="morph"
            default="none"
          >
            <div
              className="product-hero"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <Suspense
            fallback={
              <ViewTransition exit="slide-down" default="none">
                <DetailsSkeleton />
              </ViewTransition>
            }
          >
            <ViewTransition enter="slide-up" default="none">
              <ProductDetails slug={slug} />
            </ViewTransition>
          </Suspense>
        </div>
      </div>
    </ViewTransition>
  )
}

