/* ==========================================================================
   View transitions

   Timing is deliberately asymmetric: old content leaves quickly so it stops
   competing for attention, new content arrives more gently.
   ========================================================================== */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The ::view-transition overlay swallows pointer events, which loses clicks
   made mid-animation. Let them through to the live page. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element: grid thumbnail <-> detail hero ---------------------- */

::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}

/* Blur hides pixel-level interpolation artifacts mid-flight. */
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal: skeleton hands off to content ---------------------- */

::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* --- Directional navigation --------------------------------------------- */

::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

/* slide-y uses `transform`, slide uses `translate`, so neither clobbers the
   other when both apply to the same snapshot. */
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

@keyframes plain-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

